"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { redirect } from "next/navigation";

export default function AdminDashboard() {
  const { data: session, status } = useSession();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // 1. Yetki Kontrolü: Admin değilse hemen dışarı at
  useEffect(() => {
    if (status === "unauthenticated" || (session && (session.user as any).role !== "ADMIN")) {
      redirect("/");
    }
  }, [session, status]);

  // 2. Veri Çekme
  useEffect(() => {
    fetch("/api/admin/stats")
      .then((res) => res.json())
      .then((resData) => {
        setData(resData);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Veri çekme hatası:", err);
        setLoading(false);
      });
  }, []);

  // Yükleme ekranı (Hydration ve TypeError hatalarını önler)
  if (status === "loading" || loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] space-y-4">
        <div className="w-12 h-12 border-4 border-t-fuchsia-500 border-teal-400/20 rounded-full animate-spin"></div>
        <div className="text-teal-400 animate-pulse font-black tracking-widest uppercase text-xs">
          Sistem Verileri Senkronize Ediliyor...
        </div>
      </div>
    );
  }

  // Veri gelmiş olsa bile içinde beklediğimiz diziler var mı diye kontrol edelim (Opsiyonel Güvenlik)
  const stats = data?.stats || [];
  const messages = data?.messages || [];

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      <header>
        <h1 className="text-4xl font-black text-fuchsia-500 uppercase tracking-tighter italic underline decoration-teal-400/20 underline-offset-8">
          Terminal Kontrol
        </h1>
        <p className="text-teal-400/50 text-sm mt-3 tracking-widest uppercase font-bold">
          Sistemdeki tüm kullanıcıların performans analizi.
        </p>
      </header>
      
      {/* GRAFİKLER */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {stats.length > 0 ? (
          stats.map((user: any) => (
            <div key={user.id} className="group bg-[#0E153A] border border-teal-400/10 p-8 rounded-[2.5rem] shadow-2xl hover:border-fuchsia-500/40 transition-all duration-500">
              <div className="flex justify-between items-end mb-6">
                <div>
                  <p className="text-[10px] text-teal-500/40 uppercase font-black tracking-widest mb-1">Kullanıcı</p>
                  <span className="text-white text-xl font-bold tracking-tight group-hover:text-fuchsia-400 transition-colors">
                    {user.name || "İsimsiz Kullanıcı"}
                  </span>
                </div>
                <span className="text-fuchsia-400 font-black text-3xl italic">{user.percentage}%</span>
              </div>
              
              <div className="w-full h-4 bg-black/40 rounded-full overflow-hidden border border-white/5 p-1">
                <div 
                  className="h-full bg-gradient-to-r from-fuchsia-600 via-purple-500 to-teal-400 rounded-full transition-all duration-[1500ms] ease-out shadow-[0_0_15px_rgba(192,38,211,0.5)]" 
                  style={{ width: `${user.percentage}%` }} 
                />
              </div>
              
              <div className="mt-4 flex justify-between items-center text-[9px] text-teal-500/50 uppercase font-black tracking-[0.2em]">
                <span>İşlenen Veri</span>
                <span>{user.total} Görev Tamamlandı</span>
              </div>
            </div>
          ))
        ) : (
          <div className="col-span-full p-10 border border-dashed border-teal-400/20 rounded-[2rem] text-center text-teal-400/30 text-xs uppercase tracking-widest">
            Analiz edilecek aktif veri bulunamadı.
          </div>
        )}
      </div>

      {/* MESAJLAR */}
      <div className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2.5rem] overflow-hidden backdrop-blur-2xl shadow-2xl">
        <div className="p-6 bg-teal-400/5 border-b border-teal-400/10 flex justify-between items-center">
          <span className="text-teal-400 font-bold uppercase text-xs tracking-[0.3em]">Merkez İletişim Hattı</span>
          <span className="px-3 py-1 bg-fuchsia-500/20 text-fuchsia-400 text-[9px] rounded-full font-black uppercase">Canlı</span>
        </div>
        
        <div className="divide-y divide-teal-400/5">
          {messages.length > 0 ? (
            messages.map((m: any) => (
              <div key={m.id} className="p-8 hover:bg-white/[0.02] transition-colors group">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <span className="text-fuchsia-400 font-bold text-sm block mb-1 group-hover:text-fuchsia-300 transition-colors">
                      {m.name}
                    </span>
                    <span className="text-[10px] text-teal-500/40 font-medium tracking-wider">{m.email}</span>
                  </div>
                  <span className="text-[10px] text-white/20 font-mono bg-black/20 px-2 py-1 rounded">
                    {new Date(m.createdAt).toLocaleDateString("tr-TR")}
                  </span>
                </div>
                <p className="text-white/70 text-sm leading-relaxed font-medium pl-4 border-l-2 border-fuchsia-500/30 group-hover:border-fuchsia-500 transition-all duration-300">
                  {m.message}
                </p>
              </div>
            ))
          ) : (
            <div className="p-16 text-center text-white/10 text-[10px] uppercase tracking-[0.5em] font-black italic">
              Mesaj Arşivi Temiz
            </div>
          )}
        </div>
      </div>
    </div>
  );
}